def frame_pair(height,width,bg,frames):
    a=[[bg]*width for _ in range(height)]
    b=[[bg]*width for _ in range(height)]
    for r0,c0,r1,c1,color,fill in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    a[r][c]=b[r][c]=color
                else:
                    b[r][c]=fill
    return a,b
